458	// --- Dispatch fork tests (CU8) ---
459	//
460	// These tests exercise the dispatch fork added in CU8 using a minimal Deps
461	// struct with injected stubs instead of the full cli.NewRootCmd() path. This
462	// avoids needing real hooks or agent binaries.
463	
464	// newDispatchTestDeps builds a Deps stub suitable for dispatch fork tests.
465	// Agents in launchableAgents get a non-nil ReviewerFor; others return nil.
466	func newDispatchTestDeps(
467		t *testing.T,
468		installed []types.AgentName,
469		launchableAgents []string,
470		multiPickerFn func(ctx context.Context, eligible []review.AgentChoice) (review.PickedAgents, error),
471		promptForAgentFn func(ctx context.Context, eligible []review.AgentChoice) (string, error),
472	) review.Deps {
473		t.Helper()
474		launchableSet := make(map[string]struct{}, len(launchableAgents))
475		for _, name := range launchableAgents {
476			launchableSet[name] = struct{}{}
477		}
478		_ = promptForAgentFn
479		_ = multiPickerFn
480		return review.Deps{
481			GetAgentsWithHooksInstalled: func(_ context.Context) []types.AgentName {
482				return installed
483			},
484			NewSilentError: func(err error) error { return err },
485			HeadHasReviewCheckpoint: func(_ context.Context) (bool, string) {
486				return false, "" // no review guard
487			},
488			ReviewerFor: func(agentName string) reviewtypes.AgentReviewer {
489				if _, ok := launchableSet[agentName]; ok {
490					return &stubDispatchReviewer{name: agentName}
491				}
492				return nil
493			},
494		}
495	}
