15	// stubSynthesisProvider is a test double for SynthesisProvider that records
16	// the prompt it received and returns a canned response.
17	type stubSynthesisProvider struct {
18		capturedPrompt string
19		response       string
20		err            error
21	}
22	
23	func (s *stubSynthesisProvider) Synthesize(_ context.Context, prompt string) (string, error) {
24		s.capturedPrompt = prompt
25		if s.err != nil {
26			return "", s.err
27		}
28		return s.response, nil
29	}
30	
31	type contextWaitingSynthesisProvider struct {
32		capturedPrompt string
33		capturedErr    error
34	}
35	
36	func (s *contextWaitingSynthesisProvider) Synthesize(ctx context.Context, prompt string) (string, error) {
37		s.capturedPrompt = prompt
38		<-ctx.Done()
39		s.capturedErr = ctx.Err()
40		return "", ctx.Err()
41	}
