43	// buildSink is a helper to construct a SynthesisSink for tests.
44	func buildSink(
45		provider review.SynthesisProvider,
46		w *bytes.Buffer,
47		inputTTY bool,
48		promptYN func(ctx context.Context, question string, def bool) (bool, error),
49		perRunPrompt string,
50	) review.SynthesisSink {
51		return review.SynthesisSink{
52			Provider:     provider,
53			Writer:       w,
54			InputTTY:     inputTTY,
55			PromptYN:     promptYN,
56			PerRunPrompt: perRunPrompt,
57		}
58	}
