700	func TestComposeMultiAgentSinks(t *testing.T) {
701		t.Parallel()
702	
703		provider := &stubCmdSynthesisProvider{}
704		noopCancel := func() {}
705	
706		tests := []struct {
707			name      string
708			isTTY     bool
709			canPrompt bool
710			provider  review.SynthesisProvider
711			wantTUI   bool
712			wantDump  bool
713			wantSynth bool
714			wantTotal int
715		}{
716			{
717				name:      "non-tty omits tui and synth",
718				isTTY:     false,
719				canPrompt: false,
720				provider:  provider,
721				wantDump:  true,
722				wantTotal: 1,
723			},
724			{
725				name:      "tty with provider and prompt appends synth after tui finalizer",
726				isTTY:     true,
727				canPrompt: true,
728				provider:  provider,
729				wantTUI:   true,
730				wantDump:  true,
731				wantSynth: true,
732				wantTotal: 4,
733			},
734			{
735				name:      "tty without provider skips synth",
736				isTTY:     true,
737				canPrompt: true,
738				provider:  nil,
739				wantTUI:   true,
740				wantDump:  true,
741				wantTotal: 3,
742			},
743			{
744				name:      "tty without prompt skips legacy synth even with provider",
745				isTTY:     true,
746				canPrompt: false,
747				provider:  provider,
748				wantTUI:   true,
749				wantDump:  true,
750				wantTotal: 3,
751			},
752		}
753	
754		for _, tt := range tests {
755			t.Run(tt.name, func(t *testing.T) {
756				t.Parallel()
757				sinks := review.ExposedComposeMultiAgentSinks(review.SinkComposeInputs{
758					Out:               &bytes.Buffer{},
759					IsTTY:             tt.isTTY,
760					CanPrompt:         tt.canPrompt,
761					AgentNames:        []string{"a", "b"},
762					CancelRun:         noopCancel,
763					SynthesisProvider: tt.provider,
764				})
765				if got := len(sinks); got != tt.wantTotal {
766					t.Fatalf("len(sinks)=%d, want %d", got, tt.wantTotal)
767				}
768				_, hasTUI := review.ExposedFindTUISink(sinks)
769				if hasTUI != tt.wantTUI {
770					t.Errorf("findTUISink found=%v, want %v", hasTUI, tt.wantTUI)
771				}
772				var hasDump, hasSynth bool
773				for _, s := range sinks {
774					switch s.(type) {
775					case review.DumpSink:
776						hasDump = true
777					case review.SynthesisSink:
778						hasSynth = true
779					}
780				}
781				if hasDump != tt.wantDump {
782					t.Errorf("DumpSink present=%v, want %v", hasDump, tt.wantDump)
783				}
784				if hasSynth != tt.wantSynth {
785					t.Errorf("SynthesisSink present=%v, want %v", hasSynth, tt.wantSynth)
786				}
787			})
788		}
789	}
