				},
			})
			sinks = append(sinks, tuiPostRunCompleteSink{tui: tui, buf: postRunOut, out: in.out})
			return sinks
		}
		sinks = append(sinks, tuiPostRunCompleteSink{tui: tui})
		sinks = append(sinks, DumpSink{W: in.out})
		return sinks
	}

	sinks = append(sinks, DumpSink{W: in.out})
	if in.synthesisProvider != nil {
