96	func runTrailWatchResolved(cmd *cobra.Command, client *api.Client, trailID, description string, jsonOutput, showPings, once bool) error {
97		ctx := cmd.Context()
98		w := cmd.OutOrStdout()
99		errW := cmd.ErrOrStderr()
100		streamPath := reviewEventsPath(trailID)
101	
102		fmt.Fprintf(errW, "Watching %s — Ctrl+C to stop\n", description)
103	
104		backoff := reconnectBackoffInitial
105		lastEventID := ""
106	
107		for {
108			closeReason, lastSeenID, err := streamOnce(ctx, client, streamPath, lastEventID, jsonOutput, showPings, w, errW)
109			if lastSeenID != "" {
110				lastEventID = lastSeenID
111			}
112	
113			// Context cancelled (Ctrl+C) — exit cleanly.
114			if ctx.Err() != nil {
115				return nil //nolint:nilerr // ctx.Err() is the expected cancellation path; surface as clean exit
116			}
117	
118			if once {
119				switch closeReason {
120				case streamCloseTerminal:
121					return err
122				case streamCloseForbidden:
123					return NewSilentError(errors.New("stream access revoked"))
124				case streamCloseError:
125					if err == nil {
126						err = errors.New("stream error reported by server")
127					}
128					return NewSilentError(err)
129				case streamCloseTransport:
130					return err
131				case streamCloseReconnect, streamCloseDone:
132					return nil
133				}
134			}
135	
136			switch closeReason {
137			case streamCloseTerminal:
138				return err
139			case streamCloseDone:
140				return nil
141			case streamCloseForbidden:
142				return NewSilentError(errors.New("stream access revoked"))
143			case streamCloseReconnect:
144				// Clean server-initiated reconnect (max_duration). No backoff.
145				backoff = reconnectBackoffInitial
146				continue
147			case streamCloseError:
148				// Server emitted `event: error` — reconnect with backoff.
149				fmt.Fprintf(errW, "stream error reported by server, reconnecting in %s\n", backoff)
150			case streamCloseTransport:
151				// Network/transport error.
152				if err != nil {
153					fmt.Fprintf(errW, "stream disconnected (%v), reconnecting in %s\n", err, backoff)
154				}
155			}
156	
157			// Sleep with cancellation.
158			select {
159			case <-ctx.Done():
160				return nil
161			case <-time.After(backoff):
162			}
163			backoff *= 2
164			if backoff > reconnectBackoffCap {
165				backoff = reconnectBackoffCap
166			}
167		}
168	}
