225	type streamCloseReason int
226	
227	const (
228		streamCloseTransport streamCloseReason = iota // network/transport error
229		streamCloseReconnect                          // server `event: reconnect`
230		streamCloseForbidden                          // server `event: forbidden`
231		streamCloseError                              // server `event: error`
232		streamCloseDone                               // context cancellation
233		streamCloseTerminal                           // non-recoverable HTTP status (401/403/404/410)
234	)
235	
236	// terminalHTTPStatuses are HTTP response codes for which retrying the SSE
237	// stream cannot succeed: auth failures (401/403) and resource-not-found-style
238	// errors (404/410). 429 is intentionally *not* terminal — it's a transient
239	// rate-limit signal that should back off and retry.
240	var terminalHTTPStatuses = [...]int{
241		http.StatusUnauthorized, // 401
242		http.StatusForbidden,    // 403
243		http.StatusNotFound,     // 404
244		http.StatusGone,         // 410
245	}
246	
247	func isTerminalHTTPError(err error) bool {
248		for _, code := range terminalHTTPStatuses {
249			if api.IsHTTPErrorStatus(err, code) {
250				return true
251			}
252		}
253		return false
254	}
255	
256	// streamOnce opens a single SSE connection, prints events until it closes for
257	// any reason, and returns the close reason plus the last `id:` observed (so
258	// the caller can pass it as `Last-Event-ID` on reconnect).
259	//
260	//nolint:cyclop,gocognit // SSE framing parser is naturally branchy; splitting hurts readability
261	func streamOnce(
262		ctx context.Context,
263		client *api.Client,
264		path string,
265		lastEventID string,
266		jsonOutput, showPings bool,
267		w, errW io.Writer,
268	) (streamCloseReason, string, error) {
269		headers := http.Header{}
270		headers.Set("Accept", "text/event-stream")
271		headers.Set("Cache-Control", "no-cache")
272		if lastEventID != "" {
273			headers.Set("Last-Event-ID", lastEventID)
274		}
275	
276		resp, err := client.GetStream(ctx, path, headers)
277		if err != nil {
278			return streamCloseTransport, "", fmt.Errorf("open SSE stream: %w", err)
279		}
280		defer resp.Body.Close()
281	
282		if err := checkTrailResponse(resp); err != nil {
283			// Terminal: surface the error and don't reconnect. 429 deliberately
284			// falls through to streamCloseTransport so the caller backs off.
285			if isTerminalHTTPError(err) {
286				return streamCloseTerminal, "", err
287			}
288			return streamCloseTransport, "", err
289		}
290	
291		scanner := bufio.NewScanner(resp.Body)
292		// SSE frames can be larger than the default 64KiB scanner buffer when a
293		// review event carries long comment bodies; bump to 1 MiB to match the API's
294		// per-comment limits.
295		scanner.Buffer(make([]byte, 0, 64*1024), 1<<20)
296	
297		var (
298			eventName  string
299			dataLines  []string
300			eventID    string // id of the in-progress frame (reset on flush)
301			lastSeenID string // most recent SSE id from any frame that includes one
302		)
303	
304		flush := func() (streamCloseReason, bool) {
305			defer func() {
306				eventName = ""
307				dataLines = nil
308				eventID = ""
309			}()
310			if eventName == "" && len(dataLines) == 0 {
311				return streamCloseTransport, false
312			}
313			data := strings.Join(dataLines, "\n")
314			printSSEEvent(w, errW, eventName, data, jsonOutput)
315	
316			if eventID != "" {
317				lastSeenID = eventID
318			}
319	
320			switch eventName {
321			case sseEventReconnect:
322				return streamCloseReconnect, true
323			case sseEventForbidden:
324				return streamCloseForbidden, true
325			case sseEventError:
326				return streamCloseError, true
327			}
328			return streamCloseTransport, false
329		}
330	
331		for scanner.Scan() {
332			line := scanner.Text()
333	
334			// Blank line dispatches the event.
335			if line == "" {
336				if reason, done := flush(); done {
337					return reason, lastSeenID, nil
338				}
339				continue
340			}
341	
342			// Comment / keepalive line.
343			if strings.HasPrefix(line, ":") {
344				if showPings {
345					fmt.Fprintln(errW, "ping:", strings.TrimSpace(strings.TrimPrefix(line, ":")))
346				}
347				continue
348			}
349	
350			field, value, ok := strings.Cut(line, ":")
351			if !ok {
352				// Field-only line (no colon) — per spec the value is empty.
353				field = line
354				value = ""
355			}
356			// Per SSE spec: a single leading space after the colon is ignored.
357			value = strings.TrimPrefix(value, " ")
358	
359			switch field {
360			case "event":
361				eventName = value
362			case "data":
363				dataLines = append(dataLines, value)
364			case "id":
365				eventID = value
366			case "retry":
367				// Ignored — we manage backoff client-side.
368			}
369		}
370	
371		if err := scanner.Err(); err != nil {
372			// Context cancellation surfaces here as a wrapped "context canceled".
373			if errors.Is(err, context.Canceled) || ctx.Err() != nil {
374				return streamCloseDone, lastSeenID, nil
375			}
376			return streamCloseTransport, lastSeenID, fmt.Errorf("read SSE stream: %w", err)
377		}
378		return streamCloseTransport, lastSeenID, nil
379	}
