381	// printSSEEvent renders a single SSE event in either human-readable or
382	// json-line form. `data` may be empty (e.g. for the rare frame with only an
383	// `event:` line) — we still print something so the caller sees it.
384	func printSSEEvent(w, errW io.Writer, eventName, data string, jsonOutput bool) {
385		if jsonOutput {
386			// Emit a JSON envelope so consumers can reliably parse with
387			// `jq`/scripts. The data field is preserved verbatim if it isn't
388			// valid JSON; otherwise it's inlined as a sub-object.
389			envelope := map[string]any{"event": eventName}
390			if data != "" {
391				var sub any
392				if err := json.Unmarshal([]byte(data), &sub); err == nil {
393					envelope["data"] = sub
394				} else {
395					envelope["data"] = data
396				}
397			}
398			out, err := json.Marshal(envelope)
399			if err != nil {
400				fmt.Fprintf(errW, "failed to marshal event: %v\n", err)
401				return
402			}
403			fmt.Fprintln(w, string(out))
404			return
405		}
406	
407		switch eventName {
408		case sseEventReady:
409			printReadyEvent(w, data)
410			return
411		case sseEventReconnect:
412			fmt.Fprintln(errW, "↻ server requested reconnect")
413			return
414		case sseEventForbidden:
415			fmt.Fprintln(errW, "✖ stream access revoked")
416			return
417		case sseEventError:
418			printStreamError(errW, data)
419			return
420		}
421	
422		if ev, ok := parseReviewStreamEvent(eventName, data); ok {
423			printReviewStreamEvent(w, ev)
424			return
425		}
426	
427		// Fallback for unknown events or unparseable payloads: print raw.
428		fmt.Fprintf(w, "%s: %s\n", eventName, truncateForLog(data, 500))
429	}
