464	func printStreamError(errW io.Writer, data string) {
465		var p struct {
466			Message string `json:"message"`
467		}
468		if jerr := json.Unmarshal([]byte(data), &p); jerr != nil {
469			// Best-effort: server payload may be missing or malformed; we still
