502		}
503	
504		switch ev.EventType {
505		case "code_version.created":
506			fmt.Fprintf(w, "%scode version %s created (head %s)\n", prefix, ev.TargetID, payloadString(ev.Payload, "head_sha"))
507		case "code_version.base_sha_set":
