539		case "suggested_change.check_result", "suggested_change.apply_result":
540			fmt.Fprintf(w, "%s%s for %s: %s\n", prefix, ev.EventType, payloadString(ev.Payload, "suggested_change_id"), payloadString(ev.Payload, "status"))
541		case "thread.created":
542			fmt.Fprintf(w, "%sthread %s created for finding %s\n", prefix, ev.TargetID, payloadString(ev.Payload, "review_comment_id"))
543		case "thread.message_added":
544			fmt.Fprintf(w, "%sthread message %s added by %s\n", prefix, ev.TargetID, actor)
545		case "thread.message_edited":
546			fmt.Fprintf(w, "%sthread message %s edited by %s\n", prefix, ev.TargetID, actor)
547		case "comment.linked":
