556	func payloadString(payload map[string]any, key string) string {
557		if payload == nil {
558			return ""
559		}
560		v, ok := payload[key]
561		if !ok || v == nil {
562			return ""
563		}
564		switch t := v.(type) {
565		case string:
566			return t
567		case fmt.Stringer:
568			return t.String()
569		default:
570			return fmt.Sprint(t)
571		}
572	}
