574	// truncateForLog clips body text on a rune boundary so a single multi-line
575	// payload doesn't blow up the watch view. Newlines collapse to spaces.
576	func truncateForLog(s string, maxRunes int) string {
577		s = strings.ReplaceAll(s, "\r\n", " ")
578		s = strings.ReplaceAll(s, "\n", " ")
579		rs := []rune(s)
580		if len(rs) <= maxRunes {
581			return s
582		}
583		return string(rs[:maxRunes]) + "…"
584	}
